import React, { useEffect, useRef, useState } from 'react';
import {
  Animated,
  Dimensions,
  Easing,
  ScrollView,
  Text,
  TouchableOpacity,
  View,
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { DAILY_ARTICLES, DailyArticle, QuizQuestion } from '../../store/appStore';

const { width: SCREEN_W, height: SCREEN_H } = Dimensions.get('window');

// ─── Confetti particle ────────────────────────────────────────────────────────

const CONFETTI_COLORS = [
  '#00ff00', '#ccff33', '#ffffff', '#00cc44',
  '#aaff00', '#66ff66', '#00ffaa',
];

function ConfettiParticle({ delay }: { delay: number }) {
  const x = useRef(new Animated.Value(Math.random() * SCREEN_W)).current;
  const y = useRef(new Animated.Value(-20)).current;
  const rot = useRef(new Animated.Value(0)).current;
  const opacity = useRef(new Animated.Value(1)).current;
  const color = CONFETTI_COLORS[Math.floor(Math.random() * CONFETTI_COLORS.length)];
  const size = 8 + Math.random() * 8;
  const isRect = Math.random() > 0.5;

  useEffect(() => {
    Animated.sequence([
      Animated.delay(delay),
      Animated.parallel([
        Animated.timing(y, {
          toValue: SCREEN_H + 40,
          duration: 2200 + Math.random() * 1000,
          easing: Easing.linear,
          useNativeDriver: true,
        }),
        Animated.timing(rot, {
          toValue: 6,
          duration: 2200 + Math.random() * 1000,
          easing: Easing.linear,
          useNativeDriver: true,
        }),
        Animated.sequence([
          Animated.delay(1600),
          Animated.timing(opacity, {
            toValue: 0,
            duration: 600,
            useNativeDriver: true,
          }),
        ]),
      ]),
    ]).start();
  }, []);

  const rotate = rot.interpolate({
    inputRange: [0, 6],
    outputRange: ['0deg', `${360 * (Math.random() > 0.5 ? 1 : -1) * 3}deg`],
  });

  return (
    <Animated.View
      style={{
        position: 'absolute',
        left: x,
        top: 0,
        opacity,
        transform: [{ translateY: y }, { rotate }],
        width: isRect ? size * 0.6 : size,
        height: size,
        borderRadius: isRect ? 2 : size / 2,
        backgroundColor: color,
      }}
    />
  );
}

function Confetti() {
  const count = 60;
  return (
    <View
      style={{
        position: 'absolute',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        pointerEvents: 'none',
      }}
      // @ts-ignore
      pointerEvents="none"
    >
      {Array.from({ length: count }).map((_, i) => (
        <ConfettiParticle key={i} delay={i * 40} />
      ))}
    </View>
  );
}

// ─── Article view ─────────────────────────────────────────────────────────────

function ArticleView({
  article,
  onStartQuiz,
  quizDoneToday,
  learnPoints,
}: {
  article: DailyArticle;
  onStartQuiz: () => void;
  quizDoneToday: boolean;
  learnPoints: number;
}) {
  return (
    <>
      {/* Tag + meta */}
      <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 12 }}>
        <View
          style={{
            backgroundColor: 'rgba(0,255,0,0.12)',
            borderRadius: 6,
            paddingHorizontal: 10,
            paddingVertical: 4,
            borderWidth: 1,
            borderColor: '#00ff00',
            marginRight: 12,
          }}
        >
          <Text style={{ color: '#00ff00', fontSize: 10, fontWeight: '900', letterSpacing: 1.5 }}>
            {article.tag}
          </Text>
        </View>
        <Text style={{ color: '#555', fontSize: 12, fontWeight: '600' }}>
          {article.readTime}
        </Text>
      </View>

      {/* Title */}
      <Text
        style={{
          fontSize: 26,
          fontWeight: '900',
          color: '#ffffff',
          lineHeight: 34,
          marginBottom: 12,
        }}
      >
        {article.title}
      </Text>

      {/* Subtitle */}
      <Text
        style={{
          fontSize: 15,
          color: '#8aa18f',
          lineHeight: 24,
          marginBottom: 24,
          fontStyle: 'italic',
        }}
      >
        {article.subtitle}
      </Text>

      {/* Divider */}
      <View style={{ height: 1, backgroundColor: '#2b4330', marginBottom: 24 }} />

      {/* Body paragraphs */}
      {article.body.map((para, i) => (
        <Text
          key={i}
          style={{
            fontSize: 15,
            color: '#dddddd',
            lineHeight: 26,
            marginBottom: 18,
          }}
        >
          {para}
        </Text>
      ))}

      {/* Source */}
      <View
        style={{
          backgroundColor: '#1a1a2e',
          borderRadius: 10,
          padding: 14,
          marginBottom: 28,
          borderLeftWidth: 3,
          borderLeftColor: '#2b4330',
        }}
      >
        <Text style={{ color: '#555', fontSize: 11, fontWeight: '700', letterSpacing: 0.5, marginBottom: 4 }}>
          SOURCE
        </Text>
        <Text style={{ color: '#8aa18f', fontSize: 12, lineHeight: 18 }}>
          {article.source}
        </Text>
      </View>

      {/* Quiz CTA */}
      {quizDoneToday ? (
        <View
          style={{
            backgroundColor: '#161d18',
            borderRadius: 16,
            padding: 20,
            alignItems: 'center',
            borderWidth: 1.5,
            borderColor: '#2b4330',
            marginBottom: 20,
          }}
        >
          <Ionicons name="checkmark-circle-outline" size={32} color="#00ff00" style={{ marginBottom: 8 }} />
          <Text style={{ color: '#00ff00', fontWeight: '900', fontSize: 16, marginBottom: 4 }}>
            Quiz Complete
          </Text>
          <Text style={{ color: '#8aa18f', fontSize: 13, textAlign: 'center', lineHeight: 20 }}>
            You passed today's quiz.{'\n'}Total points: {learnPoints} 🏆
          </Text>
        </View>
      ) : (
        <TouchableOpacity
          onPress={onStartQuiz}
          style={{
            backgroundColor: '#00ff00',
            borderRadius: 16,
            paddingVertical: 18,
            alignItems: 'center',
            marginBottom: 20,
          }}
        >
          <Text style={{ color: '#000000', fontWeight: '900', fontSize: 16, letterSpacing: 0.5 }}>
            Take the Quiz →
          </Text>
        </TouchableOpacity>
      )}
    </>
  );
}

// ─── Quiz view ────────────────────────────────────────────────────────────────

type AnswerState = 'unanswered' | 'correct' | 'wrong';

function QuizView({
  questions,
  onComplete,
}: {
  questions: QuizQuestion[];
  onComplete: (passed: boolean, score: number) => void;
}) {
  const [qIndex, setQIndex] = useState(0);
  const [selected, setSelected] = useState<number | null>(null);
  const [answerState, setAnswerState] = useState<AnswerState>('unanswered');
  const [correctCount, setCorrectCount] = useState(0);

  const current = questions[qIndex];
  const isLast = qIndex === questions.length - 1;

  const handleSelect = (optionIndex: number) => {
    if (answerState !== 'unanswered') return;
    setSelected(optionIndex);
    const correct = optionIndex === current.correctIndex;
    setAnswerState(correct ? 'correct' : 'wrong');
    if (correct) setCorrectCount((c) => c + 1);
  };

  const handleNext = () => {
    if (isLast) {
      const finalCorrect = answerState === 'correct' ? correctCount : correctCount;
      const pct = Math.round((finalCorrect / questions.length) * 100);
      onComplete(pct >= 80, pct);
    } else {
      setQIndex((i) => i + 1);
      setSelected(null);
      setAnswerState('unanswered');
    }
  };

  const optionColor = (i: number): string => {
    if (answerState === 'unanswered') return '#1a1a2e';
    if (i === current.correctIndex) return '#123524';
    if (i === selected && answerState === 'wrong') return '#2f1a1a';
    return '#1a1a2e';
  };

  const optionBorder = (i: number): string => {
    if (answerState === 'unanswered') return '#2b4330';
    if (i === current.correctIndex) return '#00ff00';
    if (i === selected && answerState === 'wrong') return '#ff5a5a';
    return '#2b4330';
  };

  const optionTextColor = (i: number): string => {
    if (answerState === 'unanswered') return '#ffffff';
    if (i === current.correctIndex) return '#00ff00';
    if (i === selected && answerState === 'wrong') return '#ff8d8d';
    return '#888888';
  };

  return (
    <View>
      {/* Progress */}
      <View style={{ marginBottom: 20 }}>
        <Text style={{ color: '#8aa18f', fontSize: 12, fontWeight: '700', letterSpacing: 0.5, marginBottom: 10 }}>
          QUESTION {qIndex + 1} OF {questions.length}
        </Text>
        <View style={{ height: 6, backgroundColor: '#333333', borderRadius: 3, overflow: 'hidden' }}>
          <View
            style={{
              width: `${((qIndex + 1) / questions.length) * 100}%`,
              height: '100%',
              backgroundColor: '#00ff00',
            }}
          />
        </View>
      </View>

      {/* Question card */}
      <View
        style={{
          backgroundColor: '#161d18',
          borderRadius: 20,
          padding: 22,
          marginBottom: 16,
          borderWidth: 1.5,
          borderColor: '#2b4330',
        }}
      >
        <Text style={{ color: '#ffffff', fontSize: 18, fontWeight: '800', lineHeight: 28 }}>
          {current.question}
        </Text>
      </View>

      {/* Options */}
      {current.options.map((option, i) => (
        <TouchableOpacity
          key={i}
          onPress={() => handleSelect(i)}
          style={{
            backgroundColor: optionColor(i),
            borderRadius: 14,
            padding: 16,
            marginBottom: 10,
            borderWidth: 1.5,
            borderColor: optionBorder(i),
            flexDirection: 'row',
            alignItems: 'center',
          }}
        >
          <View
            style={{
              width: 28,
              height: 28,
              borderRadius: 14,
              backgroundColor:
                answerState !== 'unanswered' && i === current.correctIndex
                  ? '#00ff00'
                  : answerState !== 'unanswered' && i === selected && answerState === 'wrong'
                  ? '#ff5a5a'
                  : '#2b4330',
              justifyContent: 'center',
              alignItems: 'center',
              marginRight: 14,
            }}
          >
            <Text
              style={{
                color:
                  answerState !== 'unanswered' &&
                  (i === current.correctIndex || (i === selected && answerState === 'wrong'))
                    ? '#000000'
                    : '#888888',
                fontWeight: '900',
                fontSize: 12,
              }}
            >
              {String.fromCharCode(65 + i)}
            </Text>
          </View>
          <Text style={{ color: optionTextColor(i), fontSize: 14, fontWeight: '600', flex: 1, lineHeight: 21 }}>
            {option}
          </Text>
        </TouchableOpacity>
      ))}

      {/* Explanation */}
      {answerState !== 'unanswered' && (
        <View
          style={{
            backgroundColor: answerState === 'correct' ? 'rgba(0,255,0,0.06)' : 'rgba(255,90,90,0.06)',
            borderRadius: 14,
            padding: 16,
            marginTop: 4,
            marginBottom: 16,
            borderLeftWidth: 3,
            borderLeftColor: answerState === 'correct' ? '#00ff00' : '#ff5a5a',
          }}
        >
          <Text
            style={{
              color: answerState === 'correct' ? '#00ff00' : '#ff8d8d',
              fontWeight: '900',
              fontSize: 12,
              marginBottom: 6,
              letterSpacing: 0.5,
            }}
          >
            {answerState === 'correct' ? '✓ CORRECT' : '✗ INCORRECT'}
          </Text>
          <Text style={{ color: '#cccccc', fontSize: 13, lineHeight: 20 }}>
            {current.explanation}
          </Text>
        </View>
      )}

      {/* Next / Finish */}
      {answerState !== 'unanswered' && (
        <TouchableOpacity
          onPress={handleNext}
          style={{
            backgroundColor: '#00ff00',
            borderRadius: 14,
            paddingVertical: 16,
            alignItems: 'center',
            marginBottom: 8,
          }}
        >
          <Text style={{ color: '#000000', fontWeight: '900', fontSize: 15, letterSpacing: 0.5 }}>
            {isLast ? 'See Results' : 'Next Question →'}
          </Text>
        </TouchableOpacity>
      )}
    </View>
  );
}

// ─── Results view ─────────────────────────────────────────────────────────────

function ResultsView({
  score,
  passed,
  learnPoints,
  onReadAgain,
}: {
  score: number;
  passed: boolean;
  learnPoints: number;
  onReadAgain: () => void;
}) {
  return (
    <View style={{ alignItems: 'center', paddingTop: 16 }}>
      <View
        style={{
          backgroundColor: '#161d18',
          borderRadius: 22,
          padding: 32,
          alignItems: 'center',
          borderWidth: 2,
          borderColor: passed ? '#00ff00' : '#2b4330',
          marginBottom: 20,
          width: '100%',
        }}
      >
        <Text style={{ fontSize: 72, marginBottom: 8 }}>
          {passed ? '🏆' : '📖'}
        </Text>
        <Text style={{ color: '#ffffff', fontWeight: '900', fontSize: 28, marginBottom: 6 }}>
          {score}%
        </Text>
        <Text
          style={{
            color: passed ? '#00ff00' : '#ff8d8d',
            fontWeight: '800',
            fontSize: 16,
            marginBottom: 12,
          }}
        >
          {passed ? 'Quiz Passed!' : 'Keep Learning'}
        </Text>
        <Text style={{ color: '#8aa18f', fontSize: 14, textAlign: 'center', lineHeight: 22 }}>
          {passed
            ? `You earned +10 points. Total: ${learnPoints} 🏆\nYour streak has been updated.`
            : 'You need 80% or higher to earn points.\nRe-read the article and try again tomorrow.'}
        </Text>
      </View>

      {!passed && (
        <TouchableOpacity
          onPress={onReadAgain}
          style={{
            backgroundColor: '#1a1a2e',
            borderRadius: 14,
            paddingVertical: 16,
            paddingHorizontal: 32,
            borderWidth: 1.5,
            borderColor: '#2b4330',
          }}
        >
          <Text style={{ color: '#8aa18f', fontWeight: '700', fontSize: 14 }}>
            Re-read Article
          </Text>
        </TouchableOpacity>
      )}
    </View>
  );
}

// ─── Main screen ──────────────────────────────────────────────────────────────

type Screen = 'article' | 'quiz' | 'results';

type Props = {
  quizDoneToday: boolean;
  learnPoints: number;
  onQuizPass: () => Promise<void>;
};

export default function LearnScreen({ quizDoneToday, learnPoints, onQuizPass }: Props) {
  const todayIndex = new Date().getDay(); // 0–6
  const article: DailyArticle = DAILY_ARTICLES[todayIndex % DAILY_ARTICLES.length];

  const [screen, setScreen] = useState<Screen>('article');
  const [quizScore, setQuizScore] = useState(0);
  const [passed, setPassed] = useState(false);
  const [showConfetti, setShowConfetti] = useState(false);

  const handleQuizComplete = async (didPass: boolean, score: number) => {
    setQuizScore(score);
    setPassed(didPass);
    setScreen('results');
    if (didPass) {
      setShowConfetti(true);
      await onQuizPass();
      setTimeout(() => setShowConfetti(false), 3000);
    }
  };

  return (
    <View style={{ flex: 1 }}>
      <ScrollView
        style={{ flex: 1 }}
        contentContainerStyle={{ paddingHorizontal: 18, paddingBottom: 40 }}
        showsVerticalScrollIndicator={false}
      >
        {/* Header */}
        <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 6, marginTop: 4 }}>
          <Ionicons name="book-outline" size={30} color="#00ff00" style={{ marginRight: 10 }} />
          <Text style={{ fontSize: 40, fontWeight: '900', color: '#ffffff' }}>Learn</Text>
        </View>
        <Text style={{ fontSize: 13, color: '#888888', marginBottom: 24, fontWeight: '600' }}>
          Today's ear health read — a new article every day.
        </Text>

        {/* Points badge */}
        <View
          style={{
            flexDirection: 'row',
            alignItems: 'center',
            backgroundColor: '#1a1a2e',
            borderRadius: 12,
            padding: 12,
            marginBottom: 24,
            borderWidth: 1,
            borderColor: '#2b4330',
            alignSelf: 'flex-start',
          }}
        >
          <Text style={{ fontSize: 16, marginRight: 8 }}>🏆</Text>
          <Text style={{ color: '#ffffff', fontWeight: '800', fontSize: 14 }}>
            {learnPoints} pts
          </Text>
          <Text style={{ color: '#555', fontSize: 13, marginLeft: 6 }}>learn points</Text>
        </View>

        {screen === 'article' && (
          <ArticleView
            article={article}
            onStartQuiz={() => setScreen('quiz')}
            quizDoneToday={quizDoneToday}
            learnPoints={learnPoints}
          />
        )}

        {screen === 'quiz' && (
          <QuizView
            questions={article.quiz}
            onComplete={handleQuizComplete}
          />
        )}

        {screen === 'results' && (
          <ResultsView
            score={quizScore}
            passed={passed}
            learnPoints={learnPoints}
            onReadAgain={() => setScreen('article')}
          />
        )}
      </ScrollView>

      {showConfetti && <Confetti />}
    </View>
  );
}
